<template><div class="page" v-if="s"><button class="back" @click="$router.push(`/analysis/${route.params.id}`)">← Back to Scenarios</button><header class="scenario-head"><div><div class="eyebrow">USER SCENARIO · {{s.id}}</div><h1>{{s.title}}</h1><p>{{s.description}}</p></div><button class="ghost-btn" @click="$router.push(`/analysis/${route.params.id}/scenario/${s.id}/wireframes`)">All Screens ({{s.stages.length}}) →</button></header><div class="tabs"><button class="tab active">Scenario Overview</button><button class="tab">Wireframes ({{s.stages.length}})</button><button class="tab">User Flow</button><button class="tab">Related Requirements</button></div><section class="card scenario-detail"><div><h2>Scenario Description</h2><p>{{s.description}}</p><div class="detail-grid"><div><b>User Goal</b><span>{{s.goal}}</span></div><div><b>Success</b><span>{{s.success}}</span></div></div></div><div><div class="section-title"><div><h2>Wireframes</h2><p>Stage {{stageIndex+1}} of {{s.stages.length}}</p></div><div><button class="round" @click="prev">‹</button><button class="round" @click="next">›</button></div></div><div class="wireframe-view"><img :src="stage.imageUrl" alt="Wireframe"/><div class="wireframe-info"><span class="badge">{{stage.type}}</span><h3>{{stage.title}}</h3><b>Purpose</b><p>{{stage.purpose}}</p><b>User actions</b><ul><li v-for="x in stage.actions" :key="x">{{x}}</li></ul></div></div></div></section></div></template>
<script setup lang="ts">import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{api}from'../api';const route=useRoute();const s=ref<any>();const stageIndex=ref(0);onMounted(async()=>{const a=await api.get(route.params.id as string);s.value=a.scenarios.find((x:any)=>x.id===route.params.scenarioId);if(s.value?.stages.some((x:any)=>!x.imageUrl)){await api.wireframes(a.id,s.value.id);const fresh=await api.get(a.id);s.value=fresh.scenarios.find((x:any)=>x.id===route.params.scenarioId)}});const stage=computed(()=>s.value?.stages[stageIndex.value]||{});function next(){if(s.value)stageIndex.value=Math.min(s.value.stages.length-1,stageIndex.value+1)}function prev(){stageIndex.value=Math.max(0,stageIndex.value-1)}</script>
